import { copyFile, readFile, writeFile } from 'node:fs/promises'

const projectLicense = new URL('../LICENSE', import.meta.url)
const decoderLicense = new URL('../licenses/jsqr-es6.txt', import.meta.url)
const viteLicense = new URL('LICENSE.md', import.meta.resolve('vite/package.json'))
const thirdPartyOutput = new URL('../dist/third-party-licenses.txt', import.meta.url)

// Vite's report only sees package modules, so include code bundled inside
// qr-scanner's worker and the runtime helpers generated by Vite itself.
const [bundledTerms, decoderTerms, viteTerms] = await Promise.all([
  readFile(thirdPartyOutput, 'utf8'),
  readFile(decoderLicense, 'utf8'),
  readFile(viteLicense, 'utf8'),
])
const viteCoreTerms = viteTerms.split('\n# Licenses of bundled dependencies')[0]

await Promise.all([
  copyFile(projectLicense, new URL('../dist/LICENSE.txt', import.meta.url)),
  writeFile(thirdPartyOutput, [
    bundledTerms.trimEnd(),
    decoderTerms.trimEnd(),
    `## Vite runtime helpers (MIT)\n\n${viteCoreTerms.trimEnd()}`,
  ].join('\n\n') + '\n'),
])
